    // Track which ids are processed
    var seenIds = {};

    // For each todo, update existing element or create new one
    // appendChild moves existing elements to the end (reordering)
    todos.forEach(function (todo) {
      var idStr = String(todo.id);
      seenIds[idStr] = true;

      var li = existingMap[idStr];
      if (li) {
        // Move to end (reorders) and update in place
        todoList.appendChild(li);

